    vm = VendingMachine()
    vm.inventory = {
        'Coke': {'price': 1.25, 'quantity': 10},
        'Chips': {'price': 2.50, 'quantity': 5}
    }
    result = vm.display_items()
    lines = result.split('\n')
    assert len(lines) == 2
    assert 'Coke - $1.25 [10]' in lines
